  // BMW's own material names -> studio materials
  materials(n, map, side, orig, THREE, api) {
    const std = o => new THREE.MeshStandardMaterial(o), phys = o => new THREE.MeshPhysicalMaterial(o);
    if (/common_Paint$/.test(n)) return api.paint;
    if (/Glass_Print_dark/.test(n)) return phys({ color: '#050506', roughness: 0.3, clearcoat: 1 });
    if (/Glass_1sided|Glass_2sided_dark/.test(n)) return phys({ color: '#0b0e12', metalness: 0.1, roughness: 0.03, transparent: true, opacity: 0.5, clearcoat: 1, envMapIntensity: 1.6, side: THREE.DoubleSide, depthWrite: false });
    if (/Glass_glossy_clear|Lens_clear/.test(n)) return phys({ color: '#ffffff', roughness: 0.02, transparent: true, opacity: 0.16, clearcoat: 1, envMapIntensity: 2, depthWrite: false });
    if (/Glass_glossy_smokedgray/.test(n)) return phys({ color: '#1a1a1c', roughness: 0.05, transparent: true, opacity: 0.55, clearcoat: 1, depthWrite: false });
    if (/Lens_red|Glass_opaque_red/.test(n)) return std({ color: '#b3121c', emissive: '#ff1022', emissiveIntensity: 0.9, roughness: 0.2 });
    if (/Glass_opaque_lightgray/.test(n)) return std({ color: '#c9ccd0', roughness: 0.3 });
    if (/Emission/.test(n)) return std({ color: '#ffffff', emissive: '#e8f2ff', emissiveIntensity: 1.2 });
    if (/LightEffect/.test(n)) return std({ color: '#ffffff', emissive: '#ffffff', emissiveIntensity: 0.25, transparent: true, opacity: 0.35, depthWrite: false });
    if (/Chrome_matte|Chrome_mat/.test(n)) return std({ color: '#b9bec4', metalness: 1, roughness: 0.3 });
    if (/Chrome|glossy_vaporized/.test(n)) return std({ color: '#d6dadf', metalness: 1, roughness: 0.08 });
    if (/Aluminum_light|Aluminium_light/.test(n)) return std({ color: '#c8ccd1', metalness: 1, roughness: 0.25 });
    if (/Aluminum_brushed|Aluminum_finegrained/.test(n)) return std({ color: '#a6abb1', metalness: 1, roughness: 0.35 });
    if (/Aluminum_matte_black/.test(n)) return std({ color: '#1d1e20', metalness: 0.8, roughness: 0.45 });
    if (/Plastic_glossy_black/.test(n)) return phys({ color: '#060708', metalness: 0.2, roughness: 0.15, clearcoat: 1, clearcoatRoughness: 0.05, side });
    if (/Plastic_grained_black|Plastic_matte_black/.test(n)) return std({ color: '#0f1012', roughness: 0.8, side });
    if (/Tire/.test(n)) return std({ color: '#111213', roughness: 0.9 });
    if (/Rim_Paint_silver/.test(n)) return phys({ color: '#c3c7cc', metalness: 0.9, roughness: 0.25, clearcoat: 0.8 });
    if (/Rim_Paint_gray/.test(n)) return phys({ color: '#6b6e72', metalness: 0.6, roughness: 0.35, clearcoat: 0.6 });
    if (/Brake_Discs/.test(n)) return std({ color: '#8b8f93', metalness: 1, roughness: 0.45 });
    if (/Emblem/.test(n)) return phys({ map: api.texture(window.CAR.emblemTexture), metalness: 0.5, roughness: 0.25, clearcoat: 1 });
    if (/LicensePlate/.test(n)) return std({ color: '#ffffff', roughness: 0.4 });
    if (/I_common_general/.test(n)) return std({ color: '#3a3533', roughness: 0.7, side });
    if (/none/.test(n)) return std({ color: '#050505', roughness: 1, side });
    return null;
  },
